import{_ as e,o as r,c as t,a2 as o}from"./chunks/framework.BCectEOt.js";const u=JSON.parse('{"title":"隱私權政策","description":"蒼藍星圖鑑應用程式與網站的隱私權政策，說明本地資料、裝置備份、聯絡郵件、資料刪除與聯絡方式。","frontmatter":{"description":"蒼藍星圖鑑應用程式與網站的隱私權政策，說明本地資料、裝置備份、聯絡郵件、資料刪除與聯絡方式。","head":[["link",{"rel":"canonical","href":"https://eurekaffeine.github.io/sapphire-star-codex/zh-hant/privacy/"}],["meta",{"property":"og:url","content":"https://eurekaffeine.github.io/sapphire-star-codex/zh-hant/privacy/"}],["meta",{"property":"og:title","content":"隱私權政策 | Sapphire Star Codex"}],["meta",{"property":"og:description","content":"蒼藍星圖鑑應用程式與網站的隱私權政策，說明本地資料、裝置備份、聯絡郵件、資料刪除與聯絡方式。"}]]},"headers":[],"relativePath":"zh-hant/privacy/index.md","filePath":"zh-hant/privacy/index.md"}'),i={name:"zh-hant/privacy/index.md"};function n(l,a,h,p,s,c){return r(),t("div",null,[...a[0]||(a[0]=[o('<h1 id="隱私權政策" tabindex="-1">隱私權政策 <a class="header-anchor" href="#隱私權政策" aria-label="Permalink to &quot;隱私權政策&quot;">​</a></h1><p>生效及更新日期：2026 年 10 月 31 日</p><p>這份政策適用於蒼藍星圖鑑（Sapphire Star Codex）的 iOS、Android、HarmonyOS 應用程式，以及本網站。開發者是 <strong>eurekaffeine（刘耀晨）</strong>。隱私相關問題可寄信至 <a href="mailto:eurekaffeine.work@gmail.com" target="_blank" rel="noreferrer">eurekaffeine.work@gmail.com</a>。</p><p>應用程式仍在開發，各平台的功能有所不同。以下說明目前應用程式與網站的資料處理方式。使用應用程式不需要註冊帳號。</p><h2 id="哪些資料儲存在裝置上" tabindex="-1">哪些資料儲存在裝置上？ <a class="header-anchor" href="#哪些資料儲存在裝置上" aria-label="Permalink to &quot;哪些資料儲存在裝置上？&quot;">​</a></h2><p>為了記住你的選擇並提供功能，應用程式會在裝置上儲存資料。依使用的平台及功能，可能包括：</p><ul><li>選擇的遊戲、語言、外觀與其他設定。</li><li>搜尋紀錄，以及用來恢復瀏覽位置的頁面狀態。</li><li>收藏的魔物、裝備及其他圖鑑資料。</li><li>儲存的配裝、自訂配裝名稱、裝飾品數量、護石和防具庫存。</li></ul><p>這些資料用於瀏覽、搜尋、收藏與配裝。應用程式不會將它們上傳給開發者，也沒有由我們營運的帳號或雲端同步服務。</p><h2 id="權限與自動收集" tabindex="-1">權限與自動收集 <a class="header-anchor" href="#權限與自動收集" aria-label="Permalink to &quot;權限與自動收集&quot;">​</a></h2><p>目前的應用程式未加入廣告、追蹤、使用分析或自動上傳當機報告的 SDK。現有功能不需要存取聯絡人、位置、相機、麥克風或相片圖庫，也不收集廣告識別碼。</p><p>作業系統和應用程式商店可能依各自的設定及政策，另外處理安裝或診斷資訊。如果平台向我們提供診斷資訊，我們會用來排查應用程式問題。</p><h2 id="聯絡我們時提供的資訊" tabindex="-1">聯絡我們時提供的資訊 <a class="header-anchor" href="#聯絡我們時提供的資訊" aria-label="Permalink to &quot;聯絡我們時提供的資訊&quot;">​</a></h2><p>當你寄信給我們，我們會收到你的電子郵件地址、信件內容，以及你主動附上的檔案。我們僅用於回覆、排查問題與處理隱私請求。請只提供處理問題所需的內容。我們不會將聯絡紀錄用於廣告或行銷郵件。</p><h2 id="網站、備份與其他服務" tabindex="-1">網站、備份與其他服務 <a class="header-anchor" href="#網站、備份與其他服務" aria-label="Permalink to &quot;網站、備份與其他服務&quot;">​</a></h2><p><strong>本網站。</strong> 網站由 GitHub Pages 託管。我們未加入流量分析、廣告 Cookie 或追蹤像素。站內搜尋在瀏覽器中執行，顯示與搜尋偏好也可能儲存在瀏覽器。造訪網站時，GitHub 會收到 IP 位址、瀏覽器資訊等技術請求資訊；詳見 <a href="https://docs.github.com/en/site-policy/privacy-policies/github-general-privacy-statement" target="_blank" rel="noreferrer">GitHub 隱私聲明</a>。</p><p><strong>裝置備份。</strong> 依你的系統設定，應用程式資料可能包含於裝置或雲端備份。備份由相應的平台服務商管理，我們無法代為讀取或刪除。</p><p><strong>郵件與外部連結。</strong> 我們使用 Gmail 接收郵件，Google 依 <a href="https://policies.google.com/privacy" target="_blank" rel="noreferrer">Google 隱私權政策</a>處理提供郵件服務所需的資訊。開啟外部網站或應用程式商店後，適用對方的隱私政策。網站託管、郵件及備份服務商可能在你所在國家或地區以外處理資訊。</p><h2 id="資料分享、保留與刪除" tabindex="-1">資料分享、保留與刪除 <a class="header-anchor" href="#資料分享、保留與刪除" aria-label="Permalink to &quot;資料分享、保留與刪除&quot;">​</a></h2><p>我們不會出售、出租個人資訊，也不會為廣告目的分享資訊。你寄來的郵件會透過上述郵件服務商處理。法律要求或你明確提出相應請求時，我們可能提供自己實際持有的資訊。</p><ul><li><strong>應用程式資料：</strong> 可透過應用程式現有的刪除功能或裝置設定清理。要清理本地資料，請選擇同時刪除應用程式與資料的選項。保留資料的卸載或封存方式不會清空資料。備份需另外管理，重新安裝時也可能恢復其中的資料。</li><li><strong>網站偏好：</strong> 會儲存在瀏覽器，直到你清除此網站的資料或瀏覽器自行清理。</li><li><strong>郵件與你分享的診斷資訊：</strong> 僅在處理問題、後續跟進或履行法律義務所需期間保留。你可以要求刪除寄給我們的資訊，法律要求保留的情況除外。</li><li><strong>服務商持有的資料：</strong> 包括備份及網站存取日誌，依服務商自己的規則保留與管理。</li></ul><p>如需存取、更正或刪除寄給我們的資訊，請透過下方信箱聯絡。僅存在你裝置上的紀錄，我們無法遠端讀取或刪除。</p><h2 id="資料安全" tabindex="-1">資料安全 <a class="header-anchor" href="#資料安全" aria-label="Permalink to &quot;資料安全&quot;">​</a></h2><p>本地資料使用作業系統提供的應用程式儲存保護。本網站使用 HTTPS。我們僅為處理支援及隱私請求而存取相關郵件，並使用郵件服務商提供的安全措施。</p><h2 id="兒童與未成年人的隱私" tabindex="-1">兒童與未成年人的隱私 <a class="header-anchor" href="#兒童與未成年人的隱私" aria-label="Permalink to &quot;兒童與未成年人的隱私&quot;">​</a></h2><p>使用應用程式不需要填寫個人資料或出生日期，我們不會有意向兒童收集個人資訊。如果家長或監護人認為孩子曾向我們提供個人資訊，請聯絡我們處理刪除事宜。</p><h2 id="政策更新" tabindex="-1">政策更新 <a class="header-anchor" href="#政策更新" aria-label="Permalink to &quot;政策更新&quot;">​</a></h2><p>資料處理方式改變時，我們會更新本頁及日期。重要變更會透過網站或應用程式更新說明告知。若新功能需要另行申請權限或取得同意，會在相應操作時提出，不會僅憑這份政策就視為你已同意。</p><h2 id="聯絡我們" tabindex="-1">聯絡我們 <a class="header-anchor" href="#聯絡我們" aria-label="Permalink to &quot;聯絡我們&quot;">​</a></h2><p>開發者：<strong>eurekaffeine（刘耀晨）</strong><br> 應用程式：<strong>蒼藍星圖鑑 / Sapphire Star Codex</strong><br> 電子郵件：<a href="mailto:eurekaffeine.work@gmail.com" target="_blank" rel="noreferrer">eurekaffeine.work@gmail.com</a></p>',29)])])}const f=e(i,[["render",n]]);export{u as __pageData,f as default};
